// Three checks, all here so you can tune them:
// 1. same supplier and same invoice number, same amount: an exact duplicate
// 2. same supplier and same number, different amount: a resend or a correction to look at
// 3. same supplier, same amount, a different number, dated close together: a likely double bill
// Supplier names and invoice numbers are normalised first, so "ACME Supplies Ltd" meets
// "Acme Supplies Limited" and "INV-000123" meets "123".
// Amounts are read strictly (see money below). A filled-in amount that cannot be read is never
// guessed: that row still takes part in the number checks, and one AMOUNT NOT READ item lists it.
const s = $('Settings').first().json;
const tolerance = Number(s.amountTolerance) || 0.01;
const windowDays = Number(s.dateWindowDays) || 45;
const dec = String(s.decimalSeparator ?? '.').trim() || '.';
if (dec !== '.' && dec !== ',') throw new Error('decimalSeparator must be "." or ","');
const thou = dec === '.' ? ',' : '.';
const currencyColumn = String(s.currencyColumn ?? '').trim();

const normSupplier = v => String(v ?? '').toLowerCase().replace(/&/g, ' and ')
  .replace(/\b(the|ltd|limited|llp|plc|inc|co|company)\b\.?/g, ' ')
  .replace(/[^a-z0-9]+/g, ' ').trim();
const normNumber = v => String(v ?? '').toUpperCase().replace(/[^A-Z0-9]/g, '')
  .replace(/^(INVOICE|INV|NO|NUMBER)+/, '').replace(/^0+(?=\d)/, '');
const isBlank = v => v == null || String(v).trim() === '';
// A number or null. Currency symbols and 3-letter capital codes are dropped. Brackets, a leading
// minus or a trailing minus make it negative. Spaces and apostrophes count as thousands marks.
// What is left must be digits with at most one decimal mark, and every thousands group must be
// exactly three digits, so "500,00" under "." and "500.00" under "," are null, not misread.
const money = v => {
  if (typeof v === 'number') return Number.isFinite(v) ? v : null;
  let t = String(v ?? '').replace(/−/g, '-').replace(/\p{Sc}/gu, ' ')
    .replace(/(?<![A-Za-z])[A-Z]{3}(?![A-Za-z])/g, ' ').trim();
  let neg = 0;
  const br = t.match(/^\(([\s\S]*)\)$/);
  if (br) { neg++; t = br[1].trim(); }
  if (/^[-+]/.test(t)) { if (t[0] === '-') neg++; t = t.slice(1).trim(); }
  if (/-$/.test(t)) { neg++; t = t.slice(0, -1).trim(); }
  if (neg > 1) return null;
  t = t.replace(/[ '’  ]+/g, thou);
  const grouped = dec === '.' ? /^[1-9]\d{0,2}(,\d{3})+(\.\d+)?$/ : /^[1-9]\d{0,2}(\.\d{3})+(,\d+)?$/;
  const plain = dec === '.' ? /^(\d+\.?\d*|\.\d+)$/ : /^(\d+,?\d*|,\d+)$/;
  if (!grouped.test(t) && !plain.test(t)) return null;
  const n = Number(t.split(thou).join('').replace(',', '.'));
  return Number.isFinite(n) ? (neg ? -n : n) : null;
};
const parseDate = v => {
  const t = String(v ?? '').trim();
  const uk = t.match(/^(\d{1,2})[\/.-](\d{1,2})[\/.-](\d{2,4})$/);
  if (uk) {
    const y = uk[3].length === 2 ? 2000 + Number(uk[3]) : Number(uk[3]);
    return Date.UTC(y, Number(uk[2]) - 1, Number(uk[1]));
  }
  const iso = Date.parse(t);
  return Number.isFinite(iso) ? iso : null;
};
const day = ms => (ms == null ? '' : new Date(ms).toISOString().slice(0, 10));

const rows = $('Read The Invoices').all().map((i, idx) => {
  const r = i.json || {};
  const amount = money(r[s.amountColumn]);
  return {
    row: idx + 2,
    supplierText: String(r[s.supplierColumn] ?? '').trim(),
    numberText: String(r[s.numberColumn] ?? '').trim(),
    supplier: normSupplier(r[s.supplierColumn]),
    number: normNumber(r[s.numberColumn]),
    amount,
    unread: amount == null && !isBlank(r[s.amountColumn]),
    currency: currencyColumn ? String(r[currencyColumn] ?? '').trim().toUpperCase() : '',
    date: parseDate(r[s.dateColumn]),
  };
}).filter(r => r.supplier);

const key = r => [r.supplier, r.number, r.amount, day(r.date)].concat(currencyColumn ? [r.currency] : []).join('|');
const out = [];
const seenPairs = new Set();
for (let i = 0; i < rows.length; i++) {
  for (let j = i + 1; j < rows.length; j++) {
    const a = rows[i], b = rows[j];
    if (a.supplier !== b.supplier) continue;
    const sameAmount = a.currency === b.currency && a.amount != null && b.amount != null && Math.abs(a.amount - b.amount) <= tolerance;
    let verdict = '';
    if (a.number && a.number === b.number) {
      verdict = sameAmount ? 'EXACT DUPLICATE' : 'SAME NUMBER, DIFFERENT AMOUNT';
    } else if (sameAmount && a.amount > 0 && a.date != null && b.date != null
               && Math.abs(a.date - b.date) / 86400000 <= windowDays) {
      verdict = 'SAME AMOUNT, DIFFERENT NUMBER';
    }
    if (!verdict) continue;
    const pairKey = [key(a), key(b)].sort().join(' || ');
    if (seenPairs.has(pairKey)) continue; // two copies of one invoice would raise the same pair twice
    seenPairs.add(pairKey);
    out.push({ json: {
      flagged_at: new Date().toISOString(),
      verdict,
      supplier: a.supplierText,
      invoice_a: a.numberText,
      invoice_b: b.numberText,
      amount_a: a.amount,
      amount_b: b.amount,
      date_a: day(a.date),
      date_b: day(b.date),
      sheet_rows: a.row + ' and ' + b.row,
      pair_key: pairKey,
    } });
  }
}
// One extra item for every amount that could not be read. Its pair_key is the sorted row list, so
// Keep Only New Pairs raises it once per distinct set of rows. The row list goes in sheet_rows.
const unread = rows.filter(r => r.unread).map(r => r.row).sort((x, y) => x - y);
if (unread.length) {
  out.push({ json: {
    flagged_at: new Date().toISOString(),
    verdict: 'AMOUNT NOT READ',
    supplier: '', invoice_a: '', invoice_b: '',
    amount_a: '', amount_b: '', date_a: '', date_b: '',
    sheet_rows: unread.join(', '),
    pair_key: 'unread|' + unread.join(','),
  } });
}
return out;

// A pair you have already been told about is not news. Only new pairs go on.
const flagged = new Set($('Read Already Flagged').all().map(i => String((i.json || {}).pair_key || '')).filter(Boolean));
return $('Find Duplicates').all().filter(i => !flagged.has(i.json.pair_key));

// One Slack message per run, however many pairs were found.
const all = $input.all().map(i => i.json);
const unread = all.filter(p => p.verdict === 'AMOUNT NOT READ');
const pairs = all.filter(p => p.verdict !== 'AMOUNT NOT READ');
const lines = pairs.slice(0, 15).map(p =>
  '- ' + p.verdict + ': ' + p.supplier + ' ' + (p.invoice_a || 'no number') + ' / ' + (p.invoice_b || 'no number')
  + ' (' + p.amount_a + (p.amount_a === p.amount_b ? '' : ' vs ' + p.amount_b) + ', rows ' + p.sheet_rows + ')');
if (pairs.length > 15) lines.push('...and ' + (pairs.length - 15) + ' more in the sheet.');
const parts = [];
if (pairs.length) parts.push(':rotating_light: *' + pairs.length + ' possible duplicate invoice pair(s). Check before anyone pays them.*\n' + lines.join('\n'));
if (unread.length) parts.push(':warning: *Amount not read* on sheet rows ' + unread[0].sheet_rows + '. Check the amount cells and the decimalSeparator setting; these rows were still checked by invoice number.');
return [{ json: { count: pairs.length, text: parts.join('\n') } }];
